begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values ('10000000-0000-0000-0000-000000000001'),('10000000-0000-0000-0000-000000000002');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.journal_entries'::regclass),'entries force RLS');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.public_stories'::regclass),'public snapshots force RLS');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$insert into public.journal_entries(id,title,body,tags) values ('20000000-0000-0000-0000-000000000001','Private title','Private words',array['private tag'])$$,'A creates private draft');
select is((select version from public.journal_entries),1,'initial version');
select is((select count(*)::int from public.public_stories),0,'draft is never public');
select throws_ok($$insert into public.journal_entries(id,user_id) values ('20000000-0000-0000-0000-000000000099','10000000-0000-0000-0000-000000000002')$$,'42501',null,'owner spoof rejected');
select throws_ok($$update public.journal_entries set user_id='10000000-0000-0000-0000-000000000002'$$,'42501',null,'owner immutable');
select throws_ok($$update public.journal_entries set version=100$$,'42501',null,'version immutable');
select throws_ok($$update public.journal_entries set created_at=now()$$,'42501',null,'timestamp immutable');
select throws_ok($$update public.journal_entries set status='public'$$,'23514',null,'no visibility loophole');
select throws_ok($$update public.journal_entries set mood='invalid'$$,'23514',null,'invalid mood rejected');
select throws_ok($$update public.journal_entries set body=repeat('x',100001)$$,'23514',null,'body limit enforced');
select lives_ok($$update public.journal_entries set body='Saved private words' where version=1$$,'A saves with expected version');
select is((select version from public.journal_entries),2,'server advances version');
select lives_ok($$update public.journal_entries set body='stale overwrite' where version=1$$,'stale save matches no rows');
select is((select body from public.journal_entries),'Saved private words','stale version preserves newer content');
select lives_ok($$insert into public.public_stories(id,user_id,title,body) values ('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','Chosen title','Chosen public words')$$,'A explicitly publishes snapshot');
select lives_ok($$update public.journal_entries set body='NEW SECRET DRAFT'$$,'A keeps editing privately');
select is((select body from public.public_stories),'Chosen public words','private edits do not change published snapshot');
select throws_ok($$select user_id from public.public_stories$$,'42501',null,'public owner metadata is not exposed');
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from public.journal_entries),0,'B cannot read A entries');
select lives_ok($$update public.journal_entries set body='attack' where id='20000000-0000-0000-0000-000000000001'$$,'B private update affects no row');
select lives_ok($$delete from public.journal_entries$$,'B cannot delete A private rows');
select lives_ok($$update public.public_stories set body='attack' where id='20000000-0000-0000-0000-000000000001'$$,'B cannot overwrite A public story');
select lives_ok($$delete from public.public_stories where id='20000000-0000-0000-0000-000000000001'$$,'B cannot unpublish A');
select throws_ok($$insert into public.public_stories(id,user_id,title,body) values ('20000000-0000-0000-0000-000000000099','10000000-0000-0000-0000-000000000001','attack','attack')$$,'42501',null,'B cannot publish as A');
select lives_ok($$insert into public.journal_entries(id,title,body) values ('20000000-0000-0000-0000-000000000002','B draft','B private words')$$,'B creates own entry');
select throws_ok($$insert into public.public_stories(id,user_id,title,body) values ('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','attack','attack')$$,null,null,'B cannot bind A entry to B snapshot');
select is((select count(*)::int from public.journal_entries),1,'B only sees B entry');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select throws_ok($$select * from public.journal_entries$$,'42501',null,'anonymous private read denied');
select throws_ok($$insert into public.journal_entries(id) values(gen_random_uuid())$$,'42501',null,'anonymous private insert denied');
select throws_ok($$update public.journal_entries set body='attack'$$,'42501',null,'anonymous private update denied');
select throws_ok($$delete from public.journal_entries$$,'42501',null,'anonymous private delete denied');
select is((select count(id)::int from public.public_stories),1,'anonymous sees only published snapshot');
select is((select body from public.public_stories),'Chosen public words','anonymous sees intended words only');
select throws_ok($$select user_id from public.public_stories$$,'42501',null,'anonymous cannot read owner identity');
select throws_ok($$select * from public.public_stories$$,'42501',null,'wildcard cannot expose hidden columns');
select throws_ok($$insert into public.public_stories(id,user_id,title,body) values(gen_random_uuid(),gen_random_uuid(),'attack','attack')$$,'42501',null,'anonymous cannot publish');
select throws_ok($$update public.public_stories set body='attack'$$,'42501',null,'anonymous cannot update story');
select throws_ok($$delete from public.public_stories$$,'42501',null,'anonymous cannot unpublish');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is((select body from public.journal_entries),'NEW SECRET DRAFT','attacks did not alter private draft');
select is((select body from public.public_stories),'Chosen public words','attacks did not alter public snapshot');
select lives_ok($$update public.public_stories set title='Revised public title' where id='20000000-0000-0000-0000-000000000001'$$,'A can explicitly update public snapshot');
select is((select title from public.public_stories),'Revised public title','public update confirmed');
select is((select count(*)::int from public.journal_entries where id='20000000-0000-0000-0000-000000000002'),0,'A cannot read B private entry');
select lives_ok($$update public.journal_entries set body='A attack' where id='20000000-0000-0000-0000-000000000002'$$,'A cannot update B private entry');
select lives_ok($$delete from public.journal_entries where id='20000000-0000-0000-0000-000000000002'$$,'A cannot delete B private entry');
select lives_ok($$delete from public.public_stories where id='20000000-0000-0000-0000-000000000001'$$,'A unpublishes');
set local role anon;
select is((select count(id)::int from public.public_stories),0,'unpublish removes public access');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$insert into public.public_stories(id,user_id,title,body) values ('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','Republished','Public')$$,'republish');
select lives_ok($$delete from public.journal_entries where id='20000000-0000-0000-0000-000000000001'$$,'A deletes own entry');
select is((select count(id)::int from public.public_stories),0,'entry deletion cascades to public snapshot');
reset role;
select is((select body from public.journal_entries where id='20000000-0000-0000-0000-000000000002'),'B private words','A cannot remove B data');
select * from finish();
rollback;
